#!/usr/bin/env ruby
require'json';require'digest';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);domains=%w[Common Login Lobby Club].to_h{|d|[d,Dir.glob(File.join(client,'assets',d,'**/*.ts'))]};rows=[];domains.keys.combination(2){|a,b|by=domains[b].group_by{|p|File.basename(p)};domains[a].each{|p|by.fetch(File.basename(p),[]).each{|q|rows<<{basename:File.basename(p),left:p.delete_prefix(client+'/'),right:q.delete_prefix(client+'/'),identical:Digest::SHA256.file(p).hexdigest==Digest::SHA256.file(q).hexdigest}}}};legacy=domains.transform_values{|files|files.count{|p|File.basename(p).include?('Legacy')||p.include?('/CompatibilityApp/')}};report={schemaVersion:1,domainTsCounts:domains.transform_values(&:length),legacyCounts:legacy,duplicateBasenames:rows,checks:{noCrossDomainDuplicateBasenames:rows.empty?,noLegacyParallelRuntime:legacy.values.all?(&:zero?)},verdict:'blocked-parallel-domain-runtime'};out=File.join(root,'docs/generated/creal03-domain-boundaries.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CREAL03 AUDITED: #{rows.length} duplicate basenames, #{legacy.values.sum} legacy runtime files"
